-- Rifts World Book 27: Adventures in Dinosaur Swamp - 27 gear rows: Eco-Wizardry constructs and Northern Gun outdoor equipment
-- 27 gear rows.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~243-adventures-in-dinosaur-swamp-gear.sql
--
-- Written by scripts/rows-sql.mjs from 1 worker file(s). Every value is
-- printable ASCII and every row cites its book. Rows are keyed on their
-- portable identity, never an id; a row already held is left as it is.

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book, vehicle_slug) VALUES
  ('ew-waterskin', 'EW Waterskin', 'rifts', 'magic', NULL, 35000, '35,000 credits; good availability', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Eco-Wizardry construct, activated by spending P.P.E. or I.S.P. A juvenile sauropod or similar bladder with a strap and bone stopper. Creation: Create Water (15), Cure Illness (15) and 60 more P.P.E. Activation: 12 P.P.E. or 24 I.S.P. Effect: as Create Water and Cure Illness; up to three gallons (11 liters) of fresh water per 24 hours, and the Cure Illness effect lasts 3 hours after activation.', 'Rifts World Book 27: Adventures in Dinosaur Swamp p.156', NULL),
  ('ew-bandages-light-healing', 'EW Bandages (Light Healing)', 'rifts', 'magic', NULL, 2000, '2,000 credits; good availability', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Eco-Wizardry construct, activated by spending P.P.E. or I.S.P. Bandages of hide and sinew, both from one animal; M.D.C. flesh (dinosaur) is needed to treat Mega-Damage beings. One of four printed healing levels. Creation: Light Healing (6) and 8 more P.P.E. Activation: 3 P.P.E. or 6 I.S.P. Duration: immediate. Effect: as the Light Healing spell.', 'Rifts World Book 27: Adventures in Dinosaur Swamp p.156', NULL),
  ('ew-bandages-heal-wounds', 'EW Bandages (Heal Wounds)', 'rifts', 'magic', NULL, 6000, '6,000 credits; good availability', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Eco-Wizardry construct, activated by spending P.P.E. or I.S.P. Bandages of hide and sinew, both from one animal; M.D.C. flesh (dinosaur) is needed to treat Mega-Damage beings. One of four printed healing levels. Creation: Heal Wounds (10) and 16 more P.P.E. Activation: 5 P.P.E. or 10 I.S.P. Duration: immediate. Effect: as the Heal Wounds spell.', 'Rifts World Book 27: Adventures in Dinosaur Swamp p.156', NULL),
  ('ew-bandages-greater-healing', 'EW Bandages (Greater Healing)', 'rifts', 'magic', NULL, 12000, '12,000 credits; good availability', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Eco-Wizardry construct, activated by spending P.P.E. or I.S.P. Bandages of hide and sinew, both from one animal; M.D.C. flesh (dinosaur) is needed to treat Mega-Damage beings. One of four printed healing levels. Creation: Greater Healing (30) and 24 more P.P.E. Activation: 12 P.P.E. or 24 I.S.P. Duration: immediate. Effect: as the Greater Healing spell.', 'Rifts World Book 27: Adventures in Dinosaur Swamp p.156', NULL),
  ('ew-bandages-super-healing', 'EW Bandages (Super Healing)', 'rifts', 'magic', NULL, 22000, '22,000 credits; good availability', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Eco-Wizardry construct, activated by spending P.P.E. or I.S.P. Bandages of hide and sinew, both from one animal; M.D.C. flesh (dinosaur) is needed to treat Mega-Damage beings. One of four printed healing levels. Creation: Super Healing (70) and 40 more P.P.E. Activation: 20 P.P.E. or 40 I.S.P. Duration: immediate. Effect: as the Super Healing spell.', 'Rifts World Book 27: Adventures in Dinosaur Swamp p.156', NULL),
  ('ew-limb-cast', 'EW Limb Cast', 'rifts', 'magic', NULL, 80000, '80,000 credits and up; rare', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Eco-Wizardry construct, activated by spending P.P.E. or I.S.P. Stiffened M.D.C. hide, straps and an intestinal conduit, all from one animal; reattaches a severed limb. Creation: Restore Limb (80) and 100 more P.P.E. Activation: 35 P.P.E. or 70 I.S.P. Duration: 1D6+4 days for a finger, toe, hand or foot; 1D8+8 days for an arm or leg, with a week of bed rest for a limb severed at the hip or shoulder. Effect: as the Restore Limb spell.', 'Rifts World Book 27: Adventures in Dinosaur Swamp p.156', NULL),
  ('ew-messenger', 'EW Messenger', 'rifts', 'magic', NULL, 4500, '4,500 credits; common', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Eco-Wizardry construct, activated by spending P.P.E. or I.S.P. The "flying tongue": feathers, an animal tongue and gut thread, which need not come from one animal. Creation: Magic Pigeon (20) and 15 more P.P.E. Activation: 9 P.P.E. or 18 I.S.P. Duration: per the creator''s level. Effect: as the Magic Pigeon spell.', 'Rifts World Book 27: Adventures in Dinosaur Swamp p.156', NULL),
  ('ew-horror-armor', 'EW Horror Armor', 'rifts', 'armor', NULL, 150000, '150,000 credits; rare', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Eco-Wizardry construct, activated by spending P.P.E. or I.S.P. Hide of a large predatory dinosaur with bone plates and tooth and claw decoration, all from one animal; a complement to the Horror Mace. Creation: Power Weapon (35), Aura of Power (4), Mystic Fulcrum (5), Armor Bizarre (15) and 75 more P.P.E. M.D.C. IS ROLLED: base 4D6+25, constant, so the mdc column is left empty. 7 P.P.E. or 14 I.S.P. adds 15 magical M.D.C. for 3 minutes, lost before the base. Activation: 15 P.P.E. or 30 I.S.P. for the Armor Bizarre, which lasts 10 minutes: Horror Factor 12, and anyone failing the roll is -3 on initiative and -1 to strike, parry, dodge and disarm against the wearer for the whole fight.', 'Rifts World Book 27: Adventures in Dinosaur Swamp p.157', NULL),
  ('ew-armored-shield', 'EW Armored Shield', 'rifts', 'armor', NULL, 14000, '14,000 credits; relatively common', NULL, 0, NULL, NULL, NULL, NULL, NULL, 20, 'Eco-Wizardry construct, activated by spending P.P.E. or I.S.P. A Stegosaur dorsal osteoderm with hide straps and bone fasteners; larger plates make shields for larger than human-sized users. 20 M.D.C. without enchantment. Creation: Power Weapon (35), Magic Shield (6) and 20 more P.P.E. Activation: 5 P.P.E. or 10 I.S.P. Duration: 10 minutes per activation. Effect: as the Magic Shield spell.', 'Rifts World Book 27: Adventures in Dinosaur Swamp p.157', NULL),
  ('ew-cradle-of-life', 'EW Cradle of Life', 'rifts', 'magic', NULL, NULL, 'Price incalculable; each is a unique structure', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Eco-Wizardry construct, activated by spending P.P.E. or I.S.P. An immobile hut of an adult sauropod rib cage and hide, lashed with sinew; usually made by several Eco-Wizards with a ley line or other magical boost, and only three tribes are known to have built one. Creation: Restoration (750), Resurrection (650) and 1,200 more P.P.E. Activation: Restoration 400 P.P.E. or 800 I.S.P.; Resurrection 300 P.P.E. or 600 I.S.P. Duration: 24 hours to restore, 48 hours to resurrect. Effect: as the Restoration and Resurrection spells.', 'Rifts World Book 27: Adventures in Dinosaur Swamp p.157', NULL),
  ('ew-spitfire-leaper-cowl', 'EW Spitfire Leaper Cowl', 'rifts', 'magic', NULL, 58000, '58,000 credits; rare', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Eco-Wizardry construct, activated by spending P.P.E. or I.S.P. A loose headpiece like a mail coif, made of Spitfire Leaper hide. Creation: Impervious to Fire (5), Fireblast (8) and 35 more P.P.E. Activation: Impervious to Fire 2 P.P.E. or 4 I.S.P. for 15 minutes, which covers magic fire, plasma and dragon fire; Fireblast 4 P.P.E. or 8 I.S.P. per blast, instantaneous. Effect: as the Impervious to Fire and Fireblast spells.', 'Rifts World Book 27: Adventures in Dinosaur Swamp p.157', NULL),
  ('ng-icss-combat-and-survival-shelter', 'Northern Gun Individual Combat and Survival Shelter (NG-ICSS)', 'rifts', 'gear', 5, 800, '800-1000 credits; common', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A three-person tent, or one or two people with room for gear; a step up from the two-person tent of the NG-S2 Basic Survival Pack. Flame resistant, waterproof, insulated to -60 F (-51 C), with a water collection system that extends water supplies up to 20%. Folds to about the size of a hardback book; two people set it up in 5 minutes. 3 ft tall, 5 ft wide, 6 ft long. Built-in battery and overhead light, 72 hours of continual operation. Standard issue among many Great Lakes mercenary companies and armies.', 'Rifts World Book 27: Adventures in Dinosaur Swamp p.158', NULL),
  ('ng-ccs-command-and-control-shelter', 'NG Command and Control Shelter (NG-CCS)', 'rifts', 'gear', 18, 3000, '3,000 credits; common', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A large modular hut-like tent with an arch support frame; four people assemble it in under 20 minutes with no special tools. Shelters connect into sealable interlocking rooms, and add-on packages include environmental controls and HVAC, N.B.C. protection and a surgical package with its own air supply. Withstands 80 mph (128 km) gusts and 15 lbs (6.8 kg) of snow per square foot for 24 hours, and years of use. 8 ft tall overall (ceiling over 7 ft), 9 ft wide, 22 ft long. Battery lighting for 144 hours; can run on a generator or E-Clips, or be converted to Techno-Wizardry. The Coalition Army makes a knock-off.', 'Rifts World Book 27: Adventures in Dinosaur Swamp p.158', NULL),
  ('ng-overland-harness-and-frame-pack', 'NG "Overland" Harness and Frame Pack', 'rifts', 'gear', NULL, 700, '700 credits', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'An expandable external-frame load bearing pack in woodland, arctic, desert, black or olive drab. Chest straps carry three magazine/utility pouches and a compass pouch, with a quick-release for the main pack. Main compartment 3000 cubic inches (49,000 cc), detachable daypack 500 cubic inches (8200 cc), many side pouches, and a lock for the NG-ICSS shelter.', 'Rifts World Book 27: Adventures in Dinosaur Swamp p.158', NULL),
  ('ng-all-in-one-utility-belt', 'NG "All-In-One" Utility Belt', 'rifts', 'gear', NULL, 400, '400 credits; 350 as part of a complete Overland package', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Locks into the Overland Harness. Four magazine pouches, each holding three rifle E-Clips or six pistol E-Clips; a large fanny pouch; a radio pouch; a one quart canteen pouch. Takes a pistol holster in place of one magazine pouch, or one or two hip holsters, or up to two leg pouches instead.', 'Rifts World Book 27: Adventures in Dinosaur Swamp p.158', NULL),
  ('ng-hunter-suit-jumpsuit', 'NG "Hunter Suit" Jumpsuit', 'rifts', 'armor', NULL, 225, '225 credits; excellent availability', NULL, 0, NULL, NULL, NULL, 7, 15, NULL, 'NG Huntsman''s Choice clothing line, not combat armor. Many pockets with magnetic strip closures; wrist and pant cuffs seal against water, air, dust, gas, biological agents and insects; reinforced knee and elbow pads. With the proper headgear, boots and gloves it is fully environmental. Standard water and wind resistant fabric, rated for limited protection in a contaminated environment. Insignia 3 credits each, per jumpsuit; special colors, patterns or modifications (including for D-Bees with extra limbs or tails) 5-50 credits per jumpsuit.', 'Rifts World Book 27: Adventures in Dinosaur Swamp p.159', NULL),
  ('ng-hunter-suit-jumpsuit-armor-plates', 'NG "Hunter Suit" Jumpsuit with Armor Plates', 'rifts', 'armor', NULL, 500, '500 credits; good availability', NULL, 0, NULL, NULL, NULL, 11, NULL, 20, 'NG Huntsman''s Choice clothing line, not combat armor. Many pockets with magnetic strip closures; wrist and pant cuffs seal against water, air, dust, gas, biological agents and insects; reinforced knee and elbow pads. With the proper headgear, boots and gloves it is fully environmental. The standard jumpsuit with its optional chest and back plates. Insignia 3 credits each, per jumpsuit; special colors, patterns or modifications (including for D-Bees with extra limbs or tails) 5-50 credits per jumpsuit.', 'Rifts World Book 27: Adventures in Dinosaur Swamp p.159', NULL),
  ('ng-hunter-suit-jumpsuit-upgraded', 'NG "Hunter Suit" Jumpsuit, Upgraded', 'rifts', 'armor', NULL, 750, '750 credits; excellent availability', NULL, 0, NULL, NULL, NULL, 12, NULL, 10, 'NG Huntsman''s Choice clothing line, not combat armor. Many pockets with magnetic strip closures; wrist and pant cuffs seal against water, air, dust, gas, biological agents and insects; reinforced knee and elbow pads. With the proper headgear, boots and gloves it is fully environmental. The upgrade made of Mega-Damage fabric. Insignia 3 credits each, per jumpsuit; special colors, patterns or modifications (including for D-Bees with extra limbs or tails) 5-50 credits per jumpsuit.', 'Rifts World Book 27: Adventures in Dinosaur Swamp p.159', NULL),
  ('ng-hunter-suit-jumpsuit-upgraded-armor-plates', 'NG "Hunter Suit" Jumpsuit, Upgraded, with Armor Plates', 'rifts', 'armor', NULL, 1050, '1,050 credits; excellent availability', NULL, 0, NULL, NULL, NULL, 16, NULL, 30, 'NG Huntsman''s Choice clothing line, not combat armor. Many pockets with magnetic strip closures; wrist and pant cuffs seal against water, air, dust, gas, biological agents and insects; reinforced knee and elbow pads. With the proper headgear, boots and gloves it is fully environmental. The Mega-Damage fabric upgrade with its optional chest and back plates. Insignia 3 credits each, per jumpsuit; special colors, patterns or modifications (including for D-Bees with extra limbs or tails) 5-50 credits per jumpsuit.', 'Rifts World Book 27: Adventures in Dinosaur Swamp p.159', NULL),
  ('ng-hunter-utilities-jacket', 'NG "Hunter Utilities" Jacket', 'rifts', 'armor', NULL, 175, '175 credits; excellent availability', NULL, 0, NULL, NULL, NULL, 5, 10, NULL, 'NG Huntsman''s Choice clothing line, made of the same fabrics as the Hunter Suit; the cuffs seal like the jumpsuit''s, but jacket and pants together are not a closed environment. Standard fabric. Insignia 3 credits each, per jacket; special colors, patterns or modifications 5-25 credits per jacket or pants.', 'Rifts World Book 27: Adventures in Dinosaur Swamp p.159', NULL),
  ('ng-hunter-utilities-jacket-armor-plates', 'NG "Hunter Utilities" Jacket with Armor Plates', 'rifts', 'armor', NULL, 425, '425 credits; good availability', NULL, 0, NULL, NULL, NULL, 9, NULL, 12, 'NG Huntsman''s Choice clothing line, made of the same fabrics as the Hunter Suit; the cuffs seal like the jumpsuit''s, but jacket and pants together are not a closed environment. The standard jacket with armor plates. Insignia 3 credits each, per jacket; special colors, patterns or modifications 5-25 credits per jacket or pants.', 'Rifts World Book 27: Adventures in Dinosaur Swamp p.159', NULL),
  ('ng-hunter-utilities-jacket-upgraded', 'NG "Hunter Utilities" Jacket, Upgraded', 'rifts', 'armor', NULL, 525, '525 credits; excellent availability', NULL, 0, NULL, NULL, NULL, 7, NULL, 8, 'NG Huntsman''s Choice clothing line, made of the same fabrics as the Hunter Suit; the cuffs seal like the jumpsuit''s, but jacket and pants together are not a closed environment. The Mega-Damage fabric upgrade. Insignia 3 credits each, per jacket; special colors, patterns or modifications 5-25 credits per jacket or pants.', 'Rifts World Book 27: Adventures in Dinosaur Swamp p.159', NULL),
  ('ng-hunter-utilities-jacket-upgraded-armor-plates', 'NG "Hunter Utilities" Jacket, Upgraded, with Armor Plates', 'rifts', 'armor', NULL, 725, '725 credits; excellent availability', NULL, 0, NULL, NULL, NULL, 12, NULL, 20, 'NG Huntsman''s Choice clothing line, made of the same fabrics as the Hunter Suit; the cuffs seal like the jumpsuit''s, but jacket and pants together are not a closed environment. The Mega-Damage fabric upgrade with armor plates. Insignia 3 credits each, per jacket; special colors, patterns or modifications 5-25 credits per jacket or pants.', 'Rifts World Book 27: Adventures in Dinosaur Swamp p.159', NULL),
  ('ng-hunter-utilities-pants', 'NG "Hunter Utilities" Pants', 'rifts', 'armor', NULL, 200, '200 credits; excellent availability', NULL, 0, NULL, NULL, NULL, 5, 11, NULL, 'NG Huntsman''s Choice clothing line, made of the same fabrics as the Hunter Suit; the cuffs seal like the jumpsuit''s, but jacket and pants together are not a closed environment. Standard fabric. Insignia 3 credits each, per jacket; special colors, patterns or modifications 5-25 credits per jacket or pants.', 'Rifts World Book 27: Adventures in Dinosaur Swamp p.159', NULL),
  ('ng-hunter-utilities-pants-upgraded', 'NG "Hunter Utilities" Pants, Upgraded', 'rifts', 'armor', NULL, 500, '500 credits; excellent availability', NULL, 0, NULL, NULL, NULL, 8, NULL, 10, 'NG Huntsman''s Choice clothing line, made of the same fabrics as the Hunter Suit; the cuffs seal like the jumpsuit''s, but jacket and pants together are not a closed environment. The Mega-Damage fabric upgrade. Insignia 3 credits each, per jacket; special colors, patterns or modifications 5-25 credits per jacket or pants.', 'Rifts World Book 27: Adventures in Dinosaur Swamp p.159', NULL),
  ('ng-hunter-tracks-boots', 'NG "Hunter Tracks" Boots', 'rifts', 'gear', NULL, 250, '250 credits; excellent availability', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Part of the Hunter Suit''s environmental seal: an adjustable magnetic closure and a magnetic lip that locks into the jumpsuit cuff. Treads in a choice of patterns; usually dark brown or black. Special colors, patterns or modifications 50 credits per pair.', 'Rifts World Book 27: Adventures in Dinosaur Swamp p.159', NULL),
  ('ng-hunter-paws-gloves', 'NG "Hunter Paws" Gloves', 'rifts', 'gear', NULL, 100, '100 credits; excellent availability', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Part of the Hunter Suit''s environmental seal, with the same magnetic sealing; from light driving gloves to arctic mittens, in the jumpsuit''s colors and patterns. Special colors, patterns or modifications 10 credits per pair.', 'Rifts World Book 27: Adventures in Dinosaur Swamp p.159', NULL);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 27 gear rows are in' AS assertion, count(*) AS got, 27 AS want
  FROM gear WHERE slug IN ('ew-waterskin', 'ew-bandages-light-healing', 'ew-bandages-heal-wounds', 'ew-bandages-greater-healing', 'ew-bandages-super-healing', 'ew-limb-cast', 'ew-messenger', 'ew-horror-armor', 'ew-armored-shield', 'ew-cradle-of-life', 'ew-spitfire-leaper-cowl', 'ng-icss-combat-and-survival-shelter', 'ng-ccs-command-and-control-shelter', 'ng-overland-harness-and-frame-pack', 'ng-all-in-one-utility-belt', 'ng-hunter-suit-jumpsuit', 'ng-hunter-suit-jumpsuit-armor-plates', 'ng-hunter-suit-jumpsuit-upgraded', 'ng-hunter-suit-jumpsuit-upgraded-armor-plates', 'ng-hunter-utilities-jacket', 'ng-hunter-utilities-jacket-armor-plates', 'ng-hunter-utilities-jacket-upgraded', 'ng-hunter-utilities-jacket-upgraded-armor-plates', 'ng-hunter-utilities-pants', 'ng-hunter-utilities-pants-upgraded', 'ng-hunter-tracks-boots', 'ng-hunter-paws-gloves') AND source_book IS NOT NULL;

